'use strict';

// ── CONFIG ────────────────────────────────────────────────────────────
var PREFIX = 'phoenix3_';
function readConfig(key, def) {
    try {
        var r = exec('settings get global ' + PREFIX + key + ' 2>/dev/null');
        if (r && r !== 'null' && r.length < 500) return r;
    } catch(e) {}
    return def !== undefined ? def : '';
}
function writeConfig(key, val) {
    exec('settings put global ' + PREFIX + key + ' ' + String(val) + ' 2>/dev/null');
}
function exec(cmd) {
    try {
        if (window.ksu  && window.ksu.exec)  return (window.ksu.exec(cmd)  || '').trim();
        if (window.mmrl && window.mmrl.exec) return (window.mmrl.exec(cmd) || '').trim();
    } catch(e) {}
    return '';
}
function openUrl(url) {
    exec('am start -a android.intent.action.VIEW -d "' + url + '" 2>/dev/null');
}

// ── TOAST ──────────────────────────────────────────────────────────────
var _tt;
function showToast(msg) {
    var t = document.getElementById('toast');
    if (!t) return;
    t.textContent = msg;
    t.style.display = 'block';
    t.style.opacity = '1';
    clearTimeout(_tt);
    _tt = setTimeout(function() {
        t.style.opacity = '0';
        setTimeout(function() { t.style.display = 'none'; }, 300);
    }, 2000);
}

// ── EXEC QUEUE — async with setTimeout(0) to keep UI responsive ──────
function execQueue(cmds, done) {
    var i = 0;
    function next() {
        if (i >= cmds.length) { if (done) done(); return; }
        var cmd = cmds[i++];
        if (cmd && cmd.trim()) {
            try { exec(cmd.trim()); } catch(e) {}
        }
        setTimeout(next, 0);
    }
    next();
}

// ── EMBER CANVAS ──────────────────────────────────────────────────────
(function() {
    var c = document.getElementById('ec'), ctx = c.getContext('2d'), em = [];
    function rs() { c.width = window.innerWidth; c.height = window.innerHeight; }
    rs(); window.addEventListener('resize', rs);
    function E() { this.reset(); }
    E.prototype.reset = function() {
        this.x = Math.random() * c.width; this.y = c.height + 10;
        this.r = Math.random() * 2 + .4;
        this.vy = Math.random() * 1.1 + .4;
        this.vx = (Math.random() - .5) * .5;
        this.life = 1; this.d = Math.random() * .005 + .003;
        this.h = Math.random() * 30 + 5;
    };
    for (var i = 0; i < 55; i++) {
        var e = new E(); e.y = Math.random() * c.height; e.life = Math.random(); em.push(e);
    }
    function draw() {
        ctx.clearRect(0, 0, c.width, c.height);
        em.forEach(function(e) {
            e.x += e.vx + Math.sin(Date.now() * .001 + e.y * .01) * .25;
            e.y -= e.vy; e.life -= e.d;
            if (e.life <= 0 || e.y < -5) e.reset();
            ctx.save(); ctx.globalAlpha = e.life * .65;
            var g = ctx.createRadialGradient(e.x, e.y, 0, e.x, e.y, e.r * 2.5);
            g.addColorStop(0, 'hsl(' + e.h + ',100%,70%)');
            g.addColorStop(1, 'hsla(' + e.h + ',100%,50%,0)');
            ctx.fillStyle = g; ctx.beginPath();
            ctx.arc(e.x, e.y, e.r * 2.5, 0, Math.PI * 2); ctx.fill();
            ctx.restore();
        });
        requestAnimationFrame(draw);
    }
    draw();
})();

// ── ASH CANVAS (splash only) ──────────────────────────────────────────
(function() {
    var c = document.getElementById('ashCanvas'), ctx = c.getContext('2d'), as = [];
    c.width = window.innerWidth; c.height = window.innerHeight;
    function A() { this.reset(); }
    A.prototype.reset = function() {
        this.x = window.innerWidth / 2 + (Math.random() - .5) * 120;
        this.y = window.innerHeight * .65;
        this.r = Math.random() * 1.5 + .3;
        this.vy = Math.random() * 1.8 + .6;
        this.vx = (Math.random() - .5) * 1.2;
        this.life = 1; this.d = Math.random() * .008 + .004;
        this.h = Math.random() * 40;
    };
    for (var i = 0; i < 80; i++) {
        var a = new A(); a.y = Math.random() * window.innerHeight; a.life = Math.random(); as.push(a);
    }
    var running = true;
    function draw() {
        if (!running) return;
        ctx.clearRect(0, 0, c.width, c.height);
        as.forEach(function(a) {
            a.x += a.vx + Math.sin(Date.now() * .002 + a.y * .02) * .4;
            a.y -= a.vy; a.life -= a.d;
            if (a.life <= 0 || a.y < -5) a.reset();
            ctx.save(); ctx.globalAlpha = a.life * .8;
            var g = ctx.createRadialGradient(a.x, a.y, 0, a.x, a.y, a.r * 3);
            g.addColorStop(0, 'hsl(' + a.h + ',100%,75%)');
            g.addColorStop(1, 'hsla(' + a.h + ',100%,55%,0)');
            ctx.fillStyle = g; ctx.beginPath();
            ctx.arc(a.x, a.y, a.r * 3, 0, Math.PI * 2); ctx.fill();
            ctx.restore();
        });
        requestAnimationFrame(draw);
    }
    draw();
    window._stopAsh = function() { running = false; };
})();

// ── SPLASH ────────────────────────────────────────────────────────────
(function() {
    var msgs = ['IGNITING','LOADING','OPTIMIZING','RISING','READY'];
    var bar = document.getElementById('spf');
    var lbl = document.getElementById('spl');
    var pct = 0;
    var iv = setInterval(function() {
        pct += Math.random() * 18 + 8;
        if (pct > 100) pct = 100;
        bar.style.width = pct + '%';
        lbl.textContent = msgs[Math.min(Math.floor(pct / 22), 4)];
        if (pct >= 100) {
            clearInterval(iv);
            setTimeout(function() {
                document.getElementById('splash').classList.add('out');
                setTimeout(function() {
                    document.getElementById('splash').style.display = 'none';
                    if (window._stopAsh) window._stopAsh();
                    initUI();
                }, 600);
            }, 400);
        }
    }, 170);
})();

// ── BANNER GIF ────────────────────────────────────────────────────────
var DEFAULT_BANNER_DATA_URL = 'data:image/webp;base64,';

function reanimateGif() {
    var src = DEFAULT_BANNER_DATA_URL;
    try {
        var custom = localStorage.getItem('ph3_banner');
        if (custom) src = custom;
    } catch(e) {}
    swapBannerSrc(src);
}

function swapBannerSrc(src) {
    var old = document.getElementById('headerBanner');
    if (!old || !old.parentNode) return;
    // Create fresh element — set src BEFORE inserting so no blank flash
    var n = document.createElement('img');
    n.id  = 'headerBanner';
    n.alt = old.alt || '';
    if (old.className)      n.className     = old.className;
    if (old.style.cssText)  n.style.cssText = old.style.cssText;
    n.src = src;
    old.parentNode.replaceChild(n, old);
}

function loadDefaultBanner() { swapBannerSrc(DEFAULT_BANNER_DATA_URL); }

// Reanimate on every resume event
document.addEventListener('visibilitychange', function() {
    if (!document.hidden) reanimateGif();
});
window.addEventListener('pageshow', function() { reanimateGif(); });
window.addEventListener('focus',    function() { reanimateGif(); });

// Fallback poll: only fires when transitioning hidden→visible
var _gifWasHidden = false;
setInterval(function() {
    var hidden = !!document.hidden;
    if (!hidden && _gifWasHidden) reanimateGif();
    _gifWasHidden = hidden;
}, 1000);


// ── BANNER PICK ───────────────────────────────────────────────────────
function onBannerPick(input) {
    if (!input.files || !input.files[0]) return;
    var url = URL.createObjectURL(input.files[0]);
    swapBannerSrc(url);
    // Also save as data URL for persistence
    var reader = new FileReader();
    reader.onload = function(e) {
        try { localStorage.setItem('ph3_banner', e.target.result); } catch(ex) {}
    };
    reader.readAsDataURL(input.files[0]);
    showToast('Banner saved');
}

// ── NAVIGATION ────────────────────────────────────────────────────────
function goPage(id, el) {
    document.querySelectorAll('.page').forEach(function(p) { p.classList.remove('active'); });
    document.getElementById('p-' + id).classList.add('active');
    document.querySelectorAll('.ni').forEach(function(n) { n.classList.remove('active'); });
    el.classList.add('active');
}

// ── STATS — real CPU via /proc/stat, real RAM via /proc/meminfo ───────
var _stat1 = null;
function parseStat(raw) {
    var m = raw.match(/cpu\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)/);
    if (!m) return null;
    var user = parseInt(m[1]), nice = parseInt(m[2]),
        sys  = parseInt(m[3]), idle = parseInt(m[4]),
        wait = parseInt(m[5]);
    return { idle: idle + wait, total: user + nice + sys + idle + wait };
}
function updateStats() {
    // CPU — two readings 500ms apart
    var r1 = exec('cat /proc/stat 2>/dev/null | head -1');
    var s1 = parseStat(r1);
    setTimeout(function() {
        var r2 = exec('cat /proc/stat 2>/dev/null | head -1');
        var s2 = parseStat(r2);
        var cpu = 0;
        if (s1 && s2) {
            var dTotal = s2.total - s1.total;
            var dIdle  = s2.idle  - s1.idle;
            cpu = dTotal > 0 ? Math.round((1 - dIdle / dTotal) * 100) : 0;
        }
        var el = document.getElementById('v-cpu');
        if (el) el.innerHTML = cpu + '<em>%</em>';
    }, 500);

    // RAM — used MB
    var memRaw = exec('cat /proc/meminfo 2>/dev/null');
    var total = 0, avail = 0;
    memRaw.split('\n').forEach(function(line) {
        var m;
        if ((m = line.match(/^MemTotal:\s+(\d+)/)))    total = parseInt(m[1]);
        if ((m = line.match(/^MemAvailable:\s+(\d+)/))) avail = parseInt(m[1]);
    });
    var usedMb = total > 0 ? Math.round((total - avail) / 1024) : 0;
    var el2 = document.getElementById('v-ram');
    if (el2) el2.innerHTML = usedMb + '<em>MB</em>';
}

// ── INIT UI ───────────────────────────────────────────────────────────
function initUI() {
    // Banner
    try {
        var b = localStorage.getItem('ph3_banner');
        if (b) { swapBannerSrc(b); } else { loadDefaultBanner(); }
    } catch(e) { loadDefaultBanner(); }

    // Stats
    document.getElementById('st-cpu').classList.add('on');
    document.getElementById('st-ram').classList.add('on');
    updateStats();
    setInterval(updateStats, 3000);

    // Active preset
    var saved = readConfig('ACTIVE_PRESET', '');
    if (saved && document.getElementById('preset-' + saved)) {
        document.getElementById('preset-' + saved).classList.add('active');
        document.getElementById('activePresetName').textContent = saved;
    }

    // Animations
    var animVal = readConfig('ANIM_SCALE', '1') || '1';
    document.getElementById('sel-anim').value = animVal;

    // Sustained
    document.getElementById('tog-sustained').checked = (readConfig('SUSTAINED','0') === '1');

    // Thermal
    document.getElementById('sel-thermal').value = readConfig('THERMAL_MODE','') || '';

    // DNS
    rebuildDnsSelect();
    updateDnsBtn();
}

