function toggleSustained(cb) {
    var on = cb.checked;
    writeConfig('SUSTAINED', on ? '1' : '0');
    exec('settings put global sustained_performance_mode ' + (on ? '1' : '0') + ' 2>/dev/null');
    showToast('Sustained Mode ' + (on ? 'ON' : 'OFF'));
}
function setAnimScale(v) {
    writeConfig('ANIM_SCALE', v);
    execQueue([
        'settings put global window_animation_scale ' + v,
        'settings put global transition_animation_scale ' + v,
        'settings put global animator_duration_scale ' + v
    ]);
    showToast('Animations ' + (v === '0' ? 'Off' : v + 'x'));
}

