// ── PURGE (MOs approach) ───────────────────────────────────────────────
function runPurge() {
    showToast('Purge running...');
    execQueue([
        'cmd activity compact all 2>/dev/null',
        'cmd activity compact system 2>/dev/null',
        'cmd package trim-caches 1073741824 2>/dev/null',
        'sync 2>/dev/null',
        'cmd storaged force-gc 2>/dev/null',
        'cmd activity compact all 2>/dev/null'
    ], function() { showToast('Purge complete ✓'); });
}

// ── FORGE ─────────────────────────────────────────────────────────────
function runForge() {
    execQueue([
        'settings put global activity_manager_constants max_cached_processes=48 2>/dev/null',
        'device_config put runtime_native usap_pool_enabled true 2>/dev/null',
        'device_config put runtime_native usap_pool_size_max 10 2>/dev/null'
    ], function() { showToast('Forge applied ✓'); });
}

// ── THERMAL ────────────────────────────────────────────────────────────
function applyThermal(v) {
    writeConfig('THERMAL_MODE', v);
    if (v === '') {
        exec('cmd thermalservice reset-override-status 2>/dev/null');
        showToast('Thermal: System Default');
    } else {
        exec('cmd thermalservice override-status ' + v + ' 2>/dev/null');
        showToast('Thermal: Mode ' + v);
    }
}

