// ── DNS ────────────────────────────────────────────────────────────────
var DNS_DEFAULTS = [
    {key:'cf',  name:'Cloudflare 1.1.1.1',  addr:'1dot1dot1dot1.cloudflare-dns.com'},
    {key:'cfs', name:'Cloudflare Security', addr:'security.cloudflare-dns.com'},
    {key:'cff', name:'Cloudflare Family',   addr:'family.cloudflare-dns.com'},
    {key:'gg',  name:'Google 8.8.8.8',      addr:'dns.google'},
    {key:'q9',  name:'Quad9 9.9.9.9',       addr:'dns.quad9.net'},
    {key:'q9e', name:'Quad9 ECS',           addr:'dns11.quad9.net'},
    {key:'ag',  name:'AdGuard',             addr:'dns.adguard-dns.com'},
    {key:'agu', name:'AdGuard Unfiltered',  addr:'unfiltered.adguard-dns.com'},
    {key:'agf', name:'AdGuard Family',      addr:'family.adguard-dns.com'},
    {key:'nd',  name:'NextDNS',             addr:'dns.nextdns.io'},
    {key:'mv',  name:'Mullvad',             addr:'base.dns.mullvad.net'},
    {key:'od',  name:'OpenDNS',             addr:'doh.opendns.com'}
];
var DNS_LIST = DNS_DEFAULTS.map(function(d) {
    var n = readConfig('DNS_NAME_' + d.key, '');
    var a = readConfig('DNS_ADDR_' + d.key, '');
    return {key:d.key, name:(n&&n!=='null')?n:d.name, addr:(a&&a!=='null')?a:d.addr};
});
var dnsActiveAddr = (function() {
    var s = readConfig('DNS_SERVER','') || ''; return s === 'null' ? '' : s;
})();
var dnsEditIdx = -1;

function rebuildDnsSelect() {
    var sel = document.getElementById('sel-dns');
    while (sel.options.length > 1) sel.remove(1);
    DNS_LIST.forEach(function(d) {
        var o = document.createElement('option');
        o.value = d.addr; o.textContent = d.name;
        o.style.background = '#0d0d10'; o.style.color = '#F0EDE8';
        sel.appendChild(o);
    });
    sel.value = dnsActiveAddr;
}
function updateDnsBtn() {
    var lbl = 'System';
    if (dnsActiveAddr) {
        var f = DNS_LIST.filter(function(d){return d.addr===dnsActiveAddr;})[0];
        lbl = f ? f.name : dnsActiveAddr;
    }
    var b = document.getElementById('dnsBtnLbl');
    if (b) b.textContent = lbl + ' \u25be';
}
function dnsShowBtn() {
    document.getElementById('dnsBtnLbl').style.display = 'block';
    document.getElementById('sel-dns').style.display = 'none';
    document.getElementById('dnsEditInline').style.display = 'none';
    document.getElementById('dnsEditBtn').style.display = 'block';
}
function dnsShowSelect() {
    document.getElementById('dnsBtnLbl').style.display = 'none';
    document.getElementById('sel-dns').style.display = 'block';
    document.getElementById('dnsEditInline').style.display = 'none';
    document.getElementById('dnsEditBtn').style.display = 'none';
}
function dnsShowEditList() {
    document.getElementById('dnsBtnLbl').style.display = 'none';
    document.getElementById('sel-dns').style.display = 'none';
    document.getElementById('dnsEditInline').style.display = 'block';
    document.getElementById('dnsEditList').style.display = 'flex';
    document.getElementById('dnsEditForm').style.display = 'none';
    document.getElementById('dnsEditBtn').style.display = 'none';
}
function toggleDnsSelect(e) {
    if (e) e.stopPropagation();
    document.getElementById('sel-dns').style.display === 'block' ? dnsShowBtn() : dnsShowSelect();
}
function onDnsChange(val) {
    dnsActiveAddr = val;
    writeConfig('DNS_SERVER', val);
    if (val) {
        exec('settings put global private_dns_mode hostname 2>/dev/null');
        exec('settings put global private_dns_specifier ' + val + ' 2>/dev/null');
    } else {
        exec('settings put global private_dns_mode off 2>/dev/null');
    }
    updateDnsBtn(); dnsShowBtn();
    var f = DNS_LIST.filter(function(d){return d.addr===val;})[0];
    showToast('DNS: ' + (f ? f.name : (val || 'System')));
}
function openDnsEdit(e) {
    if (e) e.stopPropagation();
    buildDnsEditList(); dnsShowEditList();
}
function buildDnsEditList() {
    var l = document.getElementById('dnsEditList'); l.innerHTML = '';
    DNS_LIST.forEach(function(d, i) {
        var el = document.createElement('div'); el.className = 'dns-edit-item';
        el.innerHTML = '<span>' + d.name + '</span><span style="opacity:.3;font-size:8px">\u270f\ufe0f</span>';
        el.onclick = function() { openDnsForm(i); };
        l.appendChild(el);
    });
}
function openDnsForm(i) {
    dnsEditIdx = i;
    document.getElementById('dnsFieldName').value = DNS_LIST[i].name;
    document.getElementById('dnsFieldAddr').value = DNS_LIST[i].addr;
    document.getElementById('dnsEditList').style.display = 'none';
    document.getElementById('dnsEditForm').style.display = 'block';
    document.getElementById('dnsFieldName').focus();
}
function backToDnsList() {
    document.getElementById('dnsEditForm').style.display = 'none';
    document.getElementById('dnsEditList').style.display = 'flex';
}
function saveDnsEdit() {
    var name = document.getElementById('dnsFieldName').value.trim();
    var addr = document.getElementById('dnsFieldAddr').value.trim();
    if (!name || !addr) { showToast('Fill both fields'); return; }
    var old = DNS_LIST[dnsEditIdx].addr;
    DNS_LIST[dnsEditIdx].name = name; DNS_LIST[dnsEditIdx].addr = addr;
    writeConfig('DNS_NAME_' + DNS_LIST[dnsEditIdx].key, name);
    writeConfig('DNS_ADDR_' + DNS_LIST[dnsEditIdx].key, addr);
    if (dnsActiveAddr === old) {
        dnsActiveAddr = addr; writeConfig('DNS_SERVER', addr);
        exec('settings put global private_dns_specifier ' + addr + ' 2>/dev/null');
    }
    rebuildDnsSelect(); updateDnsBtn(); dnsShowBtn();
    showToast('DNS saved');
}
function resetSingleDns() {
    if (dnsEditIdx < 0) return;
    var def = DNS_DEFAULTS[dnsEditIdx];
    var old = DNS_LIST[dnsEditIdx].addr;
    DNS_LIST[dnsEditIdx].name = def.name; DNS_LIST[dnsEditIdx].addr = def.addr;
    writeConfig('DNS_NAME_' + def.key, def.name);
    writeConfig('DNS_ADDR_' + def.key, def.addr);
    document.getElementById('dnsFieldName').value = def.name;
    document.getElementById('dnsFieldAddr').value = def.addr;
    if (dnsActiveAddr === old) {
        dnsActiveAddr = def.addr; writeConfig('DNS_SERVER', def.addr);
        exec('settings put global private_dns_specifier ' + def.addr + ' 2>/dev/null');
    }
    rebuildDnsSelect(); updateDnsBtn();
    showToast('Restored: ' + def.name);
}
document.addEventListener('click', function(e) {
    var sel = document.getElementById('sel-dns');
    var il  = document.getElementById('dnsEditInline');
    var btn = document.getElementById('dnsBtnLbl');
    var edb = document.getElementById('dnsEditBtn');
    if (sel && sel.style.display==='block' && !sel.contains(e.target) && !btn.contains(e.target)) dnsShowBtn();
    if (il && il.style.display==='block' && !il.contains(e.target) && edb && !edb.contains(e.target)) dnsShowBtn();
});
